class Solution {
public:
    int maxLevelSum(TreeNode* root) {
        queue<TreeNode*> q;
        q.push(root);
        int level = 0, bestLevel = 1;
        long long bestSum = LLONG_MIN;
        while (!q.empty()) {
            level++;
            int sz = q.size();
            long long sum = 0;
            for (int k = 0; k < sz; k++) {
                TreeNode* node = q.front();
                q.pop();
                sum += node->val;
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            if (sum > bestSum) {
                bestSum = sum;
                bestLevel = level;
            }
        }
        return bestLevel;
    }
};
